const settings = (title: string, data: Record<string, unknown>): Scene => ({
  title, node: <SettingsPage />, profile: OWNER, route: '/settings?tab=subscription', seeds: [], data,
})
const locked = (title: string, data: { fn_my_licence: unknown } & Record<string, unknown>): Scene => ({
  title, node: <SubscriptionLocked licence={data.fn_my_licence as Licence} />, profile: OWNER,
  route: '/', seeds: [], data,
})
const console_ = (title: string, data: Record<string, unknown> = {}): Scene => ({
  title, node: <PlatformPage />, profile: null, route: '/platform', seeds: [], data: { ...CONSOLE, ...data },
})

